// Turn the raw Telegram update into one clean object used by every other node.
const u = $('Telegram Trigger').first().json;
const m = u.message || {};
const from = m.from || {};
const text = m.text || m.caption || '';
const isCommand = text.startsWith('/');
const isAnonAdmin = !!m.sender_chat && m.sender_chat.id === m.chat?.id; // admin posting "as the group"
const left = m.left_chat_member || null;
const entities = [...(m.entities || []), ...(m.caption_entities || [])];

let type = 'other';
if (m.new_chat_members?.length) type = 'join';
else if (left) type = left.id === from.id && !left.is_bot ? 'leave' : 'removed'; // removed = kicked/banned (already logged)
else if (from.is_bot && !isAnonAdmin) type = 'other';
else if (isCommand) type = 'command';
else if (text) type = 'message';

const rt = m.reply_to_message;
return [{ json: {
  chatId: m.chat?.id,
  chatTitle: m.chat?.title || null,
  isGroup: ['group', 'supergroup'].includes(m.chat?.type),
  messageId: m.message_id,
  userId: from.id,
  username: from.username || null,
  firstName: from.first_name || 'there',
  isAnonAdmin,
  text,
  isCommand,
  command: isCommand ? text.split(/\s+/)[0].split('@')[0].toLowerCase() : null,
  replyTo: rt?.from ? {
    userId: rt.from.id,
    username: rt.from.username || null,
    firstName: rt.from.first_name || 'User',
    isBot: rt.from.is_bot === true,
    text: rt.text || rt.caption || null,
  } : null,
  newMembers: m.new_chat_members || [],
  leftMember: left ? { userId: left.id, username: left.username || null, firstName: left.first_name || 'User' } : null,
  hasLink: entities.some(e => ['url', 'text_link'].includes(e.type)) || /(https?:\/\/|www\.|t\.me\/)/i.test(text),
  type,
}}];

// One item per human who joined (bots are skipped).
const n = $('Normalize').first().json;
return n.newMembers
  .filter(u => !u.is_bot)
  .map(u => ({ json: { chatId: n.chatId, userId: u.id, username: u.username || null, firstName: u.first_name || 'there' } }));

// Decide if the message breaks a rule. Admins are never moderated (unless Test mode is on).
const n = $('Normalize').first().json;
const s = $('Ensure settings').first().json;
const status = $('Get sender status').first().json?.result?.status;
const isAdmin = n.isAnonAdmin || ['administrator', 'creator'].includes(status);

const words = $('Get banned words').all().map(i => String(i.json.word || '').toLowerCase()).filter(Boolean);
const lower = n.text.toLowerCase();
const hit = words.find(w => lower.includes(w));

const exempt = isAdmin && !s.test_mode;
let reason = null;
if (!exempt) {
  if (s.block_links && n.hasLink) reason = 'Links are not allowed';
  else if (hit) reason = `Banned word: "${hit}"`;
}
return [{ json: {
  violation: !!reason, isAdmin, reason,
  chatId: n.chatId, userId: n.userId, messageId: n.messageId, name: n.firstName, text: n.text, by: 'bot',
}}];

// Check the sender is an admin and work out which Telegram call to make.
const n = $('Normalize').first().json;
const s = $('Ensure settings').first().json;
const status = $('Get sender status').first().json?.result?.status;
const isAdmin = n.isAnonAdmin || ['administrator', 'creator'].includes(status);
const t = n.replyTo;
const admin = n.isAnonAdmin ? 'admin' : (n.username ? '@' + n.username : n.firstName);
const base = { chatId: n.chatId, userId: t?.userId, name: t?.firstName, by: admin, cmd: n.command, error: null };

if (!isAdmin) return [{ json: { ...base, error: '⛔ Only group admins can use this command.' } }];
if (!t) return [{ json: { ...base, error: `↩️ Reply to a member's message with ${n.command}.` } }];
if (t.isBot) return [{ json: { ...base, error: "🤖 This command can't be used on bots." } }];

const mins = s.mute_minutes || 60;
const allOn = {
  can_send_messages: true, can_send_audios: true, can_send_documents: true, can_send_photos: true,
  can_send_videos: true, can_send_video_notes: true, can_send_voice_notes: true, can_send_polls: true,
  can_send_other_messages: true, can_add_web_page_previews: true, can_invite_users: true,
};
const allOff = Object.fromEntries(Object.keys(allOn).map(k => [k, false]));
const ids = { chat_id: n.chatId, user_id: t.userId };

switch (n.command) {
  case '/warn':
    return [{ json: { ...base, kind: 'warn', reason: 'Warned by admin', text: t.text } }];
  case '/ban':
    return [{ json: { ...base, kind: 'action', method: 'banChatMember', params: ids,
      status: 'banned', event: 'ban', details: {}, okText: `🚫 ${t.firstName} was banned by ${admin}.` } }];
  case '/mute':
    return [{ json: { ...base, kind: 'action', method: 'restrictChatMember',
      params: { ...ids, permissions: allOff, until_date: Math.floor(Date.now() / 1000) + mins * 60 },
      status: 'muted', event: 'mute', details: { minutes: mins }, okText: `🔇 ${t.firstName} was muted for ${mins} minutes.` } }];
  case '/unmute':
    return [{ json: { ...base, kind: 'action', method: 'restrictChatMember', params: { ...ids, permissions: allOn },
      status: 'active', event: 'unmute', details: {}, okText: `🔊 ${t.firstName} can send messages again.` } }];
}
return [{ json: { ...base, error: 'Unknown command.' } }];
